    settingsUiTrafficOff: "Off · no recording, no proxy injection",
    settingsUiAgentBindingTitle: "Automatic agent traffic binding",
    settingsUiAgentBindingDesc:
      "Off by default. When enabled, the report agent triggered on vulnerability creation reviews existing HTTP requests/responses and links the matching traffic before writing the report.",
    settingsUiAgentBindingCost: "Reading packets and the extra tool calls increase token consumption.",
    settingsUiAgentBindingNote:
      "Reporting still works for TCP, uncaptured traffic, or when no traffic matches. This switch does not affect traffic capture, manual binding, or viewing saved evidence. It takes effect for the next round of agents; once disabled, new automatic bindings are rejected immediately.",
    settingsUiAgentBindingOn: "On · increases token consumption",
    settingsUiAgentBindingOff: "Off · manual binding still available",
    settingsUiAgentBindingEnabled: "Enabled automatic agent traffic binding",
    settingsUiAgentBindingDisabled: "Disabled automatic agent traffic binding",
    settingsUiGlobalProxyTitle: "Global proxy",
    settingsUiGlobalProxyDesc:
      "All agents' target traffic egresses through this proxy (hide the source IP / use a jump host). Supports http / https / socks5, optionally with user:pass authentication. Empty = direct connection.",
    settingsUiGlobalProxyCapture:
      "With traffic capture on, it acts as the recording proxy's upstream (traffic is still stored in full, then egresses through this proxy); with capture off, it is injected directly into the agent's bash / WebFetch egress. Independent of the web search proxy and the LLM proxy.",
    settingsUiGlobalProxyNoteLabel: "Note",
    settingsUiGlobalProxyNote:
      "with capture off, socks5 relies on each CLI tool honoring ALL_PROXY (curl works; some tools may ignore it). If you mainly use socks5, enable traffic capture — on that path the MITM does the dialing itself, invisible to tools and reliably effective.",
    settingsUiProxyAddress: "Proxy address",
    settingsUiGlobalProxyPlaceholder: "socks5://user:pass@host:1080 or http://host:port (empty = direct)",
    settingsUiGlobalProxyConfigured: "Configured · all target traffic egresses through this proxy",
    settingsUiGlobalProxyNotConfigured: "Not configured · target traffic egresses directly",
    settingsUiGlobalProxySaved: "Saved global proxy",
    settingsUiGlobalProxyCleared: "Cleared global proxy (direct connection)",
    settingsUiConstraintsTitle: "Operation constraint injection",
    settingsUiConstraintsDesc:
      'When enabled, each task\'s operation constraints (the allow/deny entries maintained under "Operation constraints" in the task overview) are spliced into the corresponding agent\'s system prompt to bound the exploration scope (e.g. "only test the current port", "no brute forcing").',
    settingsUiConstraintsNote:
      "You can control injection into the planner and the worker separately; both are on by default. Switching takes effect immediately (read on the next turn) without rebuilding agents. When off, the agent no longer sees the constraints.",
    settingsUiInjectPlanner: "Inject into planner",
    settingsUiInjectWorker: "Inject into worker",
    settingsUiExperimentalTitle: "Experimental features",
    settingsUiExperimentalDesc:
      "Mechanisms still being validated, off by default. They may change agent behavior or affect stability; enable only after understanding the impact.",
    settingsUiNoaDesc:
      "noa context compaction: the model actively compacts long conversation history (norma v0.4.0). When enabled, the four agent types integrated into the platform (planner / worker / main agent / chat) switch to noa-managed context in place of the built-in compaction, and the pre-compaction originals are archived under the task working directory for later review. Switching takes effect immediately (for runs started afterwards) without rebuilding agents; when disabled, the built-in compaction is restored immediately.",
    settingsUiNoaCompaction: "noa context compaction",
    settingsUiNoaEnabled: "Enabled noa context compaction (applies to runs started afterwards)",
    settingsUiNoaDisabled: "Disabled noa context compaction (built-in compaction restored)",
    settingsUiWebSearchTitle: "Web search",
    settingsUiWebSearchDesc:
      "This is the web search master switch + source config. Only when it is enabled can each agent's config separately choose whether to enable web_search (returns only titles/links/snippets without fetching bodies; fetching is handled by WebFetch). Web search does not go through the recording proxy and is independent of traffic capture.",
    settingsUiWebSearchSources:
      "Sources: DuckDuckGo (ddgs) (no key needed), Brave (free tier) (requires a Brave API Key), Tavily (requires a Tavily API Key) or DeepSeek (reuses the current LLM config). When the master switch is off, the per-agent web search switches are unavailable.",
    settingsUiWebSearchOn: "Master switch on · can be enabled per agent config",
    settingsUiWebSearchOff: "Off · agents cannot enable web search",
    settingsUiSearchSource: "Search source",
    settingsUiChooseSource: "Choose a source",
    settingsUiSourceDdgs: "DuckDuckGo (ddgs · free, no key)",
    settingsUiSourceBrave: "Brave (free tier · requires key)",
    settingsUiSourceTavily: "Tavily (requires key)",
    settingsUiSourceKeenable: "Keenable (keyless, optional key)",
    settingsUiSourceDeepseek: "DeepSeek (official)",
    settingsUiDeepseekTitle: "DeepSeek official web search",
    settingsUiDeepseekDesc1:
      "This source directly reuses the currently active LLM config. It therefore supports official DeepSeek models only, and that config must use the anthropic protocol — DeepSeek's OpenAI-protocol endpoint does not support server-side search. This source may stop working after switching LLM configs.",
    settingsUiDeepseekDesc2:
      "Unlike other sources, the search runs server-side on DeepSeek: each search consumes an extra model call (incurring token costs), search requests do not go through the egress proxy above and are not recorded as traffic; results contain titles and links only (no snippets); use WebFetch when you need the page body.",
    settingsUiDeepseekDesc3:
      'Verify these conditions yourself; the system does not block on them. Use the "Test search" button below to run a real search and check.',
    settingsUiBraveKeyLabel: "Brave Search API Key",
    settingsUiBraveKeyPlaceholder: "Enter Brave API Key",
    settingsUiKeyKeepPlaceholder: "Configured (leave empty to keep)",
    settingsUiBraveNeedsKey:
      "Brave is selected but no key is configured — the search tool stays disabled until you save one.",
    settingsUiBraveHelp: "The free tier allows about 2,000 queries/month. Get a key at https://brave.com/search/api/.",
    settingsUiBraveKeySaved: "Saved Brave API Key",
