    settingsUiConcurrencyInvalid: "Concurrency must be an integer greater than 0",
    settingsUiSendModeTitle: "Chat input send key binding",
    settingsUiSendModeDesc:
      "Shared by the main-agent chat inputs on the chat page and task details; takes effect immediately on selection, no saving needed. This preference lives only in this browser, does not sync with the account, and must be set again after switching browsers or clearing site data.",
    settingsUiSendModeLabel: "Send mode",
    settingsUiSendModeEnter: "Enter to send, Shift+Enter for newline",
    settingsUiSendModeCtrlEnter: "Ctrl+Enter to send, Enter for newline",
    settingsUiWebSearchSaved: "Saved web search config",
    settingsUiNoiseTitle: "Target noise",
    settingsUiNoiseDesc:
      "Paces the requests ARTEX itself sends to targets (WebFetch, http custom tools, the enrich probe) and sets the low-and-slow guidance in agent prompts. With traffic capture on, Bash commands that use the proxy (curl, wget, python-requests…) are paced too, by rate and jitter only: the in-flight, cache and retry limits apply to ARTEX's own requests. Raw scanners such as nmap, and commands that bypass the proxy, are not paced; this is best effort, not a security boundary. This setting takes precedence over ARTEX_NOISE_PROFILE and applies to the next request.",
    settingsUiNoiseOff: "Off",
    settingsUiNoiseOffLimits: "Off: requests and their timing are unchanged, and nothing is counted.",
    settingsUiNoiseQuiet: "Quiet",
    settingsUiNoiseQuietLimits:
      "2 req/s per host (burst 4), 1 in flight per host, 8 overall, jitter up to 250 ms, identical GETs of a task cached 60 s, up to 3 retries on 429/503.",
    settingsUiNoiseBalanced: "Balanced",
    settingsUiNoiseBalancedLimits:
      "5 req/s per host (burst 10), 2 in flight per host, 16 overall, jitter up to 40 ms, identical GETs of a task cached 30 s, up to 3 retries on 429/503.",
    settingsUiNoiseAggressive: "Aggressive",
    settingsUiNoiseAggressiveLimits:
      "20 req/s per host (burst 40), 4 in flight per host, 32 overall, jitter up to 5 ms, identical GETs of a task cached 10 s, up to 2 retries on 429/503.",
