    settingsUiTitle: "Sistem ayarları",
    settingsUiSubtitle: "Genel çalışma zamanı anahtarları",
    settingsUiTrafficDesc:
      "Etkinleştirildiğinde her ajanın HTTP trafiği kayıt proxy'si üzerinden tam olarak saklanır; ajanlara traffic_search / traffic_get araçları ve proxy yapılandırması enjekte edilir (istem içinde proxy notları yer alır).",
    settingsUiTrafficDescOff:
      "Kapalıyken (varsayılan) hiçbir trafik kaydedilmez: ajan proxy yapılandırması veya trafik araçları almaz ve istemde proxy ile ilgili hiçbir içerik bulunmaz. Anahtar değiştirildikten sonra ajanlar hemen yeniden oluşturulur.",
    settingsUiTrafficOn: "Açık · trafik kaydediliyor ve proxy enjekte ediliyor",
    settingsUiTrafficOff: "Kapalı · kayıt yok, proxy enjeksiyonu yok",
    settingsUiAgentBindingTitle: "Otomatik ajan trafik eşleme",
    settingsUiAgentBindingDesc:
      "Varsayılan olarak kapalıdır. Etkinleştirildiğinde, güvenlik açığı oluşturulduğunda tetiklenen rapor ajanı mevcut HTTP isteklerini/yanıtlarını inceler ve raporu yazmadan önce eşleşen trafiği ilişkilendirir.",
    settingsUiAgentBindingCost: "Paketleri okumak ve ek araç çağrıları token tüketimini artırır.",
    settingsUiAgentBindingNote:
      "Raporlama TCP, yakalanmamış trafik veya eşleşen trafik olmadığında da çalışır. Bu anahtar trafik yakalamayı, elle eşlemeyi veya kayıtlı kanıtları görüntülemeyi etkilemez. Bir sonraki ajan turunda etkili olur; kapatıldığında yeni otomatik eşlemeler hemen reddedilir.",
    settingsUiAgentBindingOn: "Açık · token tüketimini artırır",
    settingsUiAgentBindingOff: "Kapalı · elle eşleme hâlâ kullanılabilir",
    settingsUiAgentBindingEnabled: "Otomatik ajan trafik eşleme etkinleştirildi",
    settingsUiAgentBindingDisabled: "Otomatik ajan trafik eşleme devre dışı bırakıldı",
    settingsUiGlobalProxyTitle: "Genel proxy",
    settingsUiGlobalProxyDesc:
      "Tüm ajanların hedef trafiği bu proxy üzerinden çıkar (kaynak IP'yi gizleyin / atlama sunucusu kullanın). http / https / socks5 desteklenir; isteğe bağlı olarak user:pass kimlik doğrulaması eklenebilir. Boş = doğrudan bağlantı.",
    settingsUiGlobalProxyCapture:
      "Trafik yakalama açıkken kayıt proxy'sinin üst akışı olarak çalışır (trafik yine tam olarak saklanır, ardından bu proxy üzerinden çıkar); yakalama kapalıyken doğrudan ajanın bash / WebFetch çıkışına enjekte edilir. Web arama proxy'sinden ve LLM proxy'sinden bağımsızdır.",
    settingsUiGlobalProxyNoteLabel: "Not",
    settingsUiGlobalProxyNote:
      "yakalama kapalıyken socks5, her CLI aracının ALL_PROXY değişkenine uymasına bağlıdır (curl çalışır; bazı araçlar bunu yok sayabilir). Ağırlıklı olarak socks5 kullanıyorsanız trafik yakalamayı açın — bu yolda MITM bağlantıyı kendisi kurar, araçlara görünmez ve güvenilir biçimde etkilidir.",
    settingsUiProxyAddress: "Proxy adresi",
    settingsUiGlobalProxyPlaceholder: "socks5://user:pass@host:1080 veya http://host:port (boş = doğrudan)",
    settingsUiGlobalProxyConfigured: "Yapılandırıldı · tüm hedef trafiği bu proxy üzerinden çıkar",
    settingsUiGlobalProxyNotConfigured: "Yapılandırılmadı · hedef trafiği doğrudan çıkar",
    settingsUiGlobalProxySaved: "Genel proxy kaydedildi",
    settingsUiGlobalProxyCleared: "Genel proxy temizlendi (doğrudan bağlantı)",
    settingsUiConstraintsTitle: "İşlem kısıtı enjeksiyonu",
    settingsUiConstraintsDesc:
      "Etkinleştirildiğinde her görevin işlem kısıtları (görev genel görünümündeki “İşlem kısıtları” altında tutulan izin/ret kayıtları) keşif kapsamını sınırlamak için ilgili ajanın sistem istemine eklenir (ör. “yalnızca mevcut portu test et”, “kaba kuvvet denemesi yapma”).",
    settingsUiConstraintsNote:
      "Enjeksiyonu planlayıcı ve işçi için ayrı ayrı kontrol edebilirsiniz; her ikisi de varsayılan olarak açıktır. Değişiklik, ajanlar yeniden oluşturulmadan hemen etkili olur (bir sonraki turda okunur). Kapalıyken ajan kısıtları artık görmez.",
    settingsUiInjectPlanner: "Planlayıcıya enjekte et",
    settingsUiInjectWorker: "İşçiye enjekte et",
    settingsUiExperimentalTitle: "Deneysel özellikler",
    settingsUiExperimentalDesc:
      "Hâlâ doğrulanmakta olan mekanizmalar, varsayılan olarak kapalı. Ajan davranışını değiştirebilir veya kararlılığı etkileyebilir; yalnızca etkisini anladıktan sonra etkinleştirin.",
    settingsUiNoaDesc:
      "noa bağlam sıkıştırma: model uzun konuşma geçmişini etkin biçimde sıkıştırır (norma v0.4.0). Etkinleştirildiğinde platforma entegre dört ajan türü (planlayıcı / işçi / ana ajan / sohbet) yerleşik sıkıştırma yerine noa tarafından yönetilen bağlamı kullanır ve sıkıştırma öncesi özgün içerik daha sonra incelenmek üzere görev çalışma dizini altında arşivlenir. Değişiklik, ajanlar yeniden oluşturulmadan hemen etkili olur (sonradan başlatılan çalıştırmalar için); kapalıyken yerleşik sıkıştırma hemen geri yüklenir.",
    settingsUiNoaCompaction: "noa bağlam sıkıştırma",
    settingsUiNoaEnabled: "noa bağlam sıkıştırma etkinleştirildi (sonradan başlatılan çalıştırmalarda geçerli)",
    settingsUiNoaDisabled: "noa bağlam sıkıştırma devre dışı bırakıldı (yerleşik sıkıştırma geri yüklendi)",
    settingsUiWebSearchTitle: "Web araması",
    settingsUiWebSearchDesc:
      "Bu, web aramasının ana anahtarı + kaynak yapılandırmasıdır. Yalnızca etkinken her ajanın yapılandırması web_search'ün etkinleştirilip etkinleştirilmeyeceğini ayrıca seçebilir (yalnızca başlık/bağlantı/özet döndürür, gövde indirmez; indirme işini WebFetch yapar). Web araması kayıt proxy'sinden geçmez ve trafik yakalamadan bağımsızdır.",
    settingsUiWebSearchSources:
      "Kaynaklar: DuckDuckGo (ddgs) (anahtar gerekmez), Brave (ücretsiz katman) (Brave API anahtarı gerekir), Tavily (Tavily API anahtarı gerekir) veya DeepSeek (mevcut LLM yapılandırmasını yeniden kullanır). Ana anahtar kapalıyken ajan başına web arama anahtarları kullanılamaz.",
    settingsUiWebSearchOn: "Ana anahtar açık · ajan yapılandırması başına etkinleştirilebilir",
    settingsUiWebSearchOff: "Kapalı · ajanlar web aramasını etkinleştiremez",
    settingsUiSearchSource: "Arama kaynağı",
    settingsUiChooseSource: "Bir kaynak seçin",
    settingsUiSourceDdgs: "DuckDuckGo (ddgs · ücretsiz, anahtar gerekmez)",
    settingsUiSourceBrave: "Brave (ücretsiz katman · anahtar gerekir)",
    settingsUiSourceTavily: "Tavily (anahtar gerekir)",
    settingsUiSourceKeenable: "Keenable (anahtarsız, isteğe bağlı anahtar)",
    settingsUiSourceDeepseek: "DeepSeek (resmi)",
    settingsUiDeepseekTitle: "DeepSeek resmi web araması",
    settingsUiDeepseekDesc1:
      "Bu kaynak etkin LLM yapılandırmasını doğrudan yeniden kullanır. Bu nedenle yalnızca resmi DeepSeek modellerini destekler ve bu yapılandırma anthropic protokolünü kullanmalıdır — DeepSeek'in OpenAI protokollü uç noktası sunucu tarafı aramayı desteklemez. LLM yapılandırması değiştirildikten sonra bu kaynak çalışmayı durdurabilir.",
    settingsUiDeepseekDesc2:
      "Diğer kaynaklardan farklı olarak arama DeepSeek tarafında, sunucu tarafında çalışır: her arama ek bir model çağrısı tüketir (token maliyeti doğurur), arama istekleri yukarıdaki çıkış proxy'sinden geçmez ve trafik olarak kaydedilmez; sonuçlar yalnızca başlık ve bağlantı içerir (özet yok); sayfa gövdesine ihtiyacınız olduğunda WebFetch kullanın.",
    settingsUiDeepseekDesc3:
      "Bu koşulları kendiniz doğrulayın; sistem bunları engellemez. Gerçek bir arama çalıştırıp kontrol etmek için aşağıdaki “Aramayı test et” düğmesini kullanın.",
    settingsUiBraveKeyLabel: "Brave Arama API Anahtarı",
    settingsUiBraveKeyPlaceholder: "Brave API anahtarını girin",
    settingsUiKeyKeepPlaceholder: "Yapılandırıldı (korumak için boş bırakın)",
