    settingsUiBraveHelp:
      "Ücretsiz katman ayda yaklaşık 2.000 sorguya izin verir. Anahtarı https://brave.com/search/api/ adresinden alın.",
    settingsUiBraveKeySaved: "Brave API anahtarı kaydedildi",
