    settingsUiTavilyKeyPlaceholder: "Tavily API anahtarını girin (tvly-…)",
    settingsUiTavilyNeedsKey:
      "Tavily seçildi ancak anahtar yapılandırılmadı — bir anahtar kaydedene kadar arama aracı devre dışı kalır.",
    settingsUiTavilyHelp: "https://tavily.com adresinden kaydolup API anahtarı alın.",
    settingsUiTavilyKeySaved: "Tavily API anahtarı kaydedildi",
    settingsUiKeenableKeyLabel: "Keenable Arama API Anahtarı (isteğe bağlı)",
    settingsUiKeenableKeyPlaceholder: "İsteğe bağlı: anahtarsız uç nokta için boş bırakın",
    settingsUiKeenableHelp:
      "Sorgular bu örnekten çıkıp api.keenable.ai adresine gider. İstek, sağlayıcının çağıranı tanımlayabilmesi için X-Keenable-Title: ARTEX başlığını taşır. Anahtar yokken genel uç nokta IP başına hız sınırlamasına tabidir; anahtar sınırı yükseltir, ancak arka uç anahtarsız da çalışır.",
    settingsUiKeenableKeySaved: "Keenable API anahtarı kaydedildi",
