    settingsUiEgressProxyHelp:
      "Yalnızca arama uç noktalarına ulaşmak için kullanılan özel çıkış proxy'si (VPN/SOCKS vb.). Trafik kaydeden MITM proxy'siyle ilgisi yoktur; ağ engellendiğinde uç noktalara ulaşmak için kullanın.",
