    settingsUiPythonDesc:
      "Özel betik araçları Python'u bununla çalıştırır. Başlangıçta otomatik algılanır (önce python3); buraya bir venv / belirli sürüm için mutlak yol girebilirsiniz; çalışma anında otomatik algılama için boş bırakın.",
