    settingsUiWorkersTitle: "İş eşzamanlılığı · işçi ajan sayısı",
    settingsUiWorkersDesc:
      "Görev başına eşzamanlı çalışan işçi ajan sayısı (varsayılan 3). Daha yüksek değerler daha fazla paralel deneme ve daha yüksek tüketim demektir. Değişiklikler sonradan başlatılan görevlerde geçerli olur; çalışan görevler etkilenmez.",
    settingsUiWorkersSaved: "Eşzamanlı işçi ajan sayısı kaydedildi (sonradan başlatılan görevlerde geçerli olur)",
    settingsUiConcurrencyInvalid: "Eşzamanlılık 0'dan büyük bir tam sayı olmalıdır",
    settingsUiSendModeTitle: "Sohbet girişi gönderme tuşu ataması",
    settingsUiSendModeDesc:
      "Sohbet sayfasındaki ve görev ayrıntılarındaki ana ajan sohbet girişlerinde ortaktır; seçim yapıldığında hemen etkili olur, kaydetmek gerekmez. Bu tercih yalnızca bu tarayıcıda yaşar, hesapla eşitlenmez ve tarayıcı değiştirdikten veya site verilerini temizledikten sonra yeniden ayarlanmalıdır.",
    settingsUiSendModeLabel: "Gönderme modu",
    settingsUiSendModeEnter: "Göndermek için Enter, yeni satır için Shift+Enter",
    settingsUiSendModeCtrlEnter: "Göndermek için Ctrl+Enter, yeni satır için Enter",
    settingsUiWebSearchSaved: "Web arama yapılandırması kaydedildi",
    settingsUiNoiseTitle: "Hedef gürültü",
    settingsUiNoiseDesc:
      "ARTEX'in hedeflere kendisinin gönderdiği istekleri (WebFetch, http özel araçları, enrich sondası) hızlandırır ve ajan istemlerinde düşük ve yavaş yönlendirmesini belirler. Trafik yakalama açıkken proxy'yi kullanan Bash komutları (curl, wget, python-requests…) da yalnızca hız ve jitter açısından sınırlandırılır: devam eden, önbellek ve yeniden deneme sınırları ARTEX'in kendi istekleri için geçerlidir. nmap gibi ham tarayıcılar ve proxy'yi atlayan komutlar sınırlandırılmaz; bu en iyi çaba temelindedir, güvenlik sınırı değildir. Bu ayar ARTEX_NOISE_PROFILE'dan önceliklidir ve bir sonraki istekte geçerli olur.",
