    llmUiRetryIntentWhere: "Bu proje · süreç düzeyinde, tek genel kopya",
    llmUiRetryIntroAfter:
      " — her katmanı sonuna kadar açın ve tek bir aksaklık düzinelerce istek harcayabilir. Her şeyi boş bırakmak mevcut varsayılanları korur, bu sayfa var olmadan önceki davranışla aynıdır. İlk üç katman model profili başına geçersiz kılınabilir.",
    llmUiRetryIntroBefore:
      "Başarısız bir model çağrısı sırayla beş yeniden deneme katmanından geçer, en içten en dışa:",
    llmUiRetryIntroChain:
      " bağlanma → boş yanıt → aynı sağlayıcı güvenli pencere → havuz kesicisi → niyet yeniden çalıştırma",
    llmUiRetryIntroMiddle: ". Bir dış katman yalnızca içtekilerin tükettiğini alır, bu yüzden deneme sayıları ",
